CREATE TABLE `email_messages` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '租户ID',
  `store_id` int unsigned NOT NULL DEFAULT '0' COMMENT '店铺ID',
  `site` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '站点',
  `language` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '语言',
  `mail_subject` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '邮件主题',
  `mail_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '邮件内容（原文）',
  `mail_content_chinese` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '邮件内容-中文',
  `buyer_mail_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '买家邮件号',
  `ai_reply_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'AI回复内容',
  `reply_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '回复日期',
  `follow_up_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '跟进情况（0-未跟进，1-已跟进）',
  `need_reply` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否需要回复（0-不需要，1-需要）',
  `reply_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '回复文本（非必填）',
  `reply_text_time` datetime DEFAULT NULL COMMENT '提交回复时间',
  `reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='邮件信息表';
