  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_ioi_order` (`inbound_order_id`) USING BTREE,
  KEY `idx_ioi_product` (`product_id`) USING BTREE,
  KEY `idx_ioi_batch` (`batch_number`) USING BTREE
