DROP TABLE IF EXISTS `inbound_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inbound_orders` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '入库订单ID',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `order_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入库单号',
  `purchase_order_id` int DEFAULT NULL COMMENT '关联采购单ID',
  `inbound_type` enum('purchase','return','transfer','adjustment','other') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'purchase' COMMENT '入库类型',
  `warehouse` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收货仓库',
  `handler` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '经办人',
  `inbound_date` datetime DEFAULT NULL COMMENT '入库日期',
  `total_quantity` int NOT NULL DEFAULT '0' COMMENT '入库总数量',
  `total_amount` decimal(12,2) DEFAULT '0.00' COMMENT '入库总金额',
  `status` enum('draft','confirmed','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'draft' COMMENT '状态',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建人',
  `confirmed_by` int DEFAULT NULL COMMENT '确认人',
  `confirmed_at` datetime DEFAULT NULL COMMENT '确认时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_io_tenant` (`tenant_id`) USING BTREE,
  KEY `idx_io_status` (`status`) USING BTREE,
  KEY `idx_io_order_number` (`order_number`) USING BTREE,
  KEY `idx_io_po` (`purchase_order_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='入库订单表';
