  `logistics_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流方式',
  `transport_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '运输方式',
  `ship_date` date DEFAULT NULL COMMENT '发货时间',
  `estimated_available_date` date DEFAULT NULL COMMENT '预计可售时间',
