  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `estimated_arrival_date` date DEFAULT NULL COMMENT '预计到港时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `ix_inbound_shipment_details_snapshot_id` (`snapshot_id`) USING BTREE,
  KEY `ix_inbound_shipment_details_account` (`account`) USING BTREE,
  KEY `ix_inbound_shipment_details_tenant_id` (`tenant_id`) USING BTREE,
  KEY `ix_inbound_shipment_details_asin` (`asin`) USING BTREE,
  KEY `ix_inbound_shipment_details_id` (`id`) USING BTREE,
  CONSTRAINT `inbound_shipment_details_ibfk_1` FOREIGN KEY (`snapshot_id`) REFERENCES `inventory_snapshots` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=12407 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='FBA在途详情表';
