--
-- Table structure for table `inventory_actions`
--

DROP TABLE IF EXISTS `inventory_actions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_actions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '操作ID',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `product_id` int NOT NULL COMMENT '商品ID',
  `store_id` int NOT NULL COMMENT '店铺ID',
  `alert_id` int DEFAULT NULL COMMENT '关联预警ID',
  `action_type` enum('PRICE_ADJUST','AD_BUDGET','PROMOTION','RESTOCK','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型',
  `action_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作标题',
  `action_details` json DEFAULT NULL COMMENT '操作详情',
  `status` enum('PENDING','EXECUTING','SUCCESS','FAILED','CANCELLED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行状态',
  `triggered_by` enum('SYSTEM_AUTO','MANUAL','SCHEDULE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发方式',
  `result` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行结果',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `executed_by` int DEFAULT NULL COMMENT '执行人',
  `executed_at` datetime DEFAULT NULL COMMENT '执行时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `executed_by` (`executed_by`) USING BTREE,
  KEY `ix_inventory_actions_tenant_id` (`tenant_id`) USING BTREE,
  KEY `ix_inventory_actions_store_id` (`store_id`) USING BTREE,
  KEY `ix_inventory_actions_status` (`status`) USING BTREE,
  KEY `ix_inventory_actions_alert_id` (`alert_id`) USING BTREE,
  KEY `ix_inventory_actions_id` (`id`) USING BTREE,
  KEY `ix_inventory_actions_product_id` (`product_id`) USING BTREE,
  CONSTRAINT `inventory_actions_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_actions_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_actions_ibfk_3` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_actions_ibfk_4` FOREIGN KEY (`alert_id`) REFERENCES `inventory_alerts` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_actions_ibfk_5` FOREIGN KEY (`executed_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

