--
-- Table structure for table `inventory_alerts`
--

DROP TABLE IF EXISTS `inventory_alerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_alerts` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '预警ID',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `product_id` int NOT NULL COMMENT '商品ID',
  `store_id` int NOT NULL COMMENT '店铺ID',
  `alert_type` enum('LOW_STOCK','OUT_OF_STOCK','OVERSTOCK','PRICE_CHANGE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预警类型',
  `severity` enum('INFO','WARNING','DANGER','CRITICAL') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '严重程度',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预警标题',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预警描述',
  `current_stock` int DEFAULT NULL COMMENT '当前库存',
  `safe_stock` int DEFAULT NULL COMMENT '安全库存',
  `suggestions` json DEFAULT NULL COMMENT 'AI建议',
  `status` enum('NEW','ACKNOWLEDGED','PROCESSING','RESOLVED','DISMISSED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理状态',
  `priority` int DEFAULT NULL COMMENT '优先级(1-10)',
  `resolved_by` int DEFAULT NULL COMMENT '处理人',
  `resolved_at` datetime DEFAULT NULL COMMENT '处理时间',
  `resolved_note` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理备注',
  `feishu_record_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '飞书记录ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `resolved_by` (`resolved_by`) USING BTREE,
  KEY `ix_inventory_alerts_alert_type` (`alert_type`) USING BTREE,
  KEY `ix_inventory_alerts_status` (`status`) USING BTREE,
  KEY `ix_inventory_alerts_product_id` (`product_id`) USING BTREE,
  KEY `ix_inventory_alerts_store_id` (`store_id`) USING BTREE,
  KEY `ix_inventory_alerts_id` (`id`) USING BTREE,
  KEY `ix_inventory_alerts_tenant_id` (`tenant_id`) USING BTREE,
  CONSTRAINT `inventory_alerts_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_alerts_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_alerts_ibfk_3` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_alerts_ibfk_4` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

