--
-- Table structure for table `inventory_batches`
--

DROP TABLE IF EXISTS `inventory_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_batches` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '批次ID',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `product_id` int NOT NULL COMMENT '商品ID',
  `inbound_order_id` int DEFAULT NULL COMMENT '关联入库单ID',
  `inbound_item_id` int DEFAULT NULL COMMENT '关联入库明细ID',
  `stock_transfer_order_id` int DEFAULT NULL COMMENT '关联挪货单ID',
  `stock_transfer_item_id` int DEFAULT NULL COMMENT '关联挪货明细ID',
  `batch_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次号',
  `initial_quantity` int NOT NULL COMMENT '初始数量',
  `current_quantity` int NOT NULL DEFAULT '0' COMMENT '当前剩余数量',
  `locked_quantity` int NOT NULL DEFAULT '0' COMMENT '锁定数量',
  `unit_price` decimal(12,2) DEFAULT '0.00' COMMENT '采购单价',
