--
-- Table structure for table `inventory_records`
--

DROP TABLE IF EXISTS `inventory_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_records` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `product_id` int NOT NULL COMMENT '商品ID',
  `store_id` int NOT NULL COMMENT '店铺ID',
  `warehouse_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '仓库编码',
  `quantity` int NOT NULL COMMENT '当前库存',
  `quantity_in_transit` int DEFAULT NULL COMMENT '在途库存',
  `quantity_available` int NOT NULL COMMENT '可用库存',
  `quantity_reserved` int DEFAULT NULL COMMENT '预留库存',
  `safe_stock` int DEFAULT NULL COMMENT '安全库存',
  `daily_sales` int DEFAULT NULL COMMENT '日均销量',
  `days_remaining` int DEFAULT NULL COMMENT '可售天数',
  `record_date` date NOT NULL COMMENT '记录日期',
  `source` enum('MANUAL','API_SYNC','IMPORT') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据来源',
  `created_at` datetime NOT NULL DEFAULT (now()) COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT (now()) COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `ix_inventory_records_record_date` (`record_date`) USING BTREE,
  KEY `ix_inventory_records_product_id` (`product_id`) USING BTREE,
  KEY `ix_inventory_records_store_id` (`store_id`) USING BTREE,
  KEY `ix_inventory_records_tenant_id` (`tenant_id`) USING BTREE,
  KEY `ix_inventory_records_id` (`id`) USING BTREE,
  CONSTRAINT `inventory_records_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_records_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `inventory_records_ibfk_3` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

