--
-- Table structure for table `inventory_snapshots`
--

DROP TABLE IF EXISTS `inventory_snapshots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_snapshots` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  `snapshot_date` date NOT NULL COMMENT '快照日期',
  `summary_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '欧洲/北美汇总行标记',
  `asin` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ASIN',
  `parent_asin` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父ASIN',
  `msku` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MSKU',
  `fnsku` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FNSKU',
  `sku` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SKU',
  `product_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品名',
  `title` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `account` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺',
  `country` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家/地区',
  `category` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类目',
  `brand` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌',
  `replenishment_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '补货状态',
  `purchase_plan_days` int DEFAULT NULL COMMENT '采购计划天数',
  `purchase_lead_time` int DEFAULT NULL COMMENT '采购交期',
  `qc_days` int DEFAULT NULL COMMENT '质检天数',
  `overseas_to_fba_days` int DEFAULT NULL COMMENT '海外仓至FBA天数',
  `safety_days` int DEFAULT NULL COMMENT '安全天数',
  `purchase_frequency` int DEFAULT NULL COMMENT '采购频率',
  `local_ship_frequency` int DEFAULT NULL COMMENT '本地仓发货频率',
  `overseas_ship_frequency` int DEFAULT NULL COMMENT '海外仓发货频率',
  `stock_up_duration` int DEFAULT NULL COMMENT '备货时长',
  `sales_3d` float DEFAULT NULL COMMENT '3天销量',
  `sales_7d` float DEFAULT NULL COMMENT '7天销量',
  `sales_14d` float DEFAULT NULL COMMENT '14天销量',
  `sales_30d` float DEFAULT NULL COMMENT '30天销量',
  `sales_60d` float DEFAULT NULL COMMENT '60天销量',
  `sales_90d` float DEFAULT NULL COMMENT '90天销量',
  `daily_avg_3d` float DEFAULT NULL COMMENT '3天日均销量',
  `daily_avg_7d` float DEFAULT NULL COMMENT '7天日均销量',
  `daily_avg_14d` float DEFAULT NULL COMMENT '14天日均销量',
  `daily_avg_30d` float DEFAULT NULL COMMENT '30天日均销量',
  `daily_avg_60d` float DEFAULT NULL COMMENT '60天日均销量',
  `daily_avg_90d` float DEFAULT NULL COMMENT '90天日均销量',
  `days_supply_total` float DEFAULT NULL COMMENT '可售天数总',
  `days_supply_fba` float DEFAULT NULL COMMENT '可售天数FBA',
  `days_supply_fba_inbound` float DEFAULT NULL COMMENT '可售天数FBA+在途',
  `stockout_date` date DEFAULT NULL COMMENT '断货时间',
  `daily_sales` float DEFAULT NULL COMMENT '日均销量',
  `sales_forecast` float DEFAULT NULL COMMENT '销量预测',
  `fba_stock` float DEFAULT NULL COMMENT 'FBA库存',
  `fba_inbound` float DEFAULT NULL COMMENT 'FBA在途',
  `fba_inbound_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '原始在途详情文本',
  `fba_available` float DEFAULT NULL COMMENT '可售',
  `fba_pending_transfer` float DEFAULT NULL COMMENT '待调仓',
  `fba_in_transfer` float DEFAULT NULL COMMENT '调仓中',
  `fba_inbound_processing` float DEFAULT NULL COMMENT '入库中',
  `local_available` float DEFAULT NULL COMMENT '本地可用',
  `total_stock` float DEFAULT NULL COMMENT '总库存',
  `age_0_3` float DEFAULT NULL COMMENT '0-3个月库龄',
  `age_3_6` float DEFAULT NULL COMMENT '3-6个月库龄',
  `age_6_9` float DEFAULT NULL COMMENT '6-9个月库龄',
  `age_9_12` float DEFAULT NULL COMMENT '9-12个月库龄',
  `age_12_plus` float DEFAULT NULL COMMENT '12个月以上库龄',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `inspection_quantity` int DEFAULT '0' COMMENT '查验货件数量',
  `local_inventory` int DEFAULT '0' COMMENT '本地仓库存',
  `gross_margin` float DEFAULT NULL COMMENT '毛利率参考',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `ix_inventory_snapshots_sku` (`sku`) USING BTREE,
  KEY `ix_inventory_snapshots_id` (`id`) USING BTREE,
  KEY `ix_inventory_snapshots_country` (`country`) USING BTREE,
  KEY `ix_inventory_snapshots_asin` (`asin`) USING BTREE,
  KEY `ix_inventory_snapshots_tenant_id` (`tenant_id`) USING BTREE,
  KEY `ix_inventory_snapshots_account` (`account`) USING BTREE,
  KEY `ix_inventory_snapshots_snapshot_date` (`snapshot_date`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=46984 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='库存快照表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `inventory_snapshots`
--

