DROP TABLE IF EXISTS `local_inventories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `local_inventories` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  `asin` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ASIN',
  `sku` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SKU',
  `product_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品名',
  `account` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺',
  `country` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家/地区',
  `quantity` float DEFAULT NULL COMMENT '本地仓库存数量',
  `batch_date` date DEFAULT NULL COMMENT '上传批次日期',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `ix_local_inventories_account` (`account`) USING BTREE,
  KEY `ix_local_inventories_asin` (`asin`) USING BTREE,
  KEY `ix_local_inventories_sku` (`sku`) USING BTREE,
  KEY `ix_local_inventories_tenant_id` (`tenant_id`) USING BTREE,
  KEY `ix_local_inv_asin_account` (`asin`,`account`) USING BTREE,
  KEY `ix_local_inventories_batch_date` (`batch_date`) USING BTREE,
  KEY `ix_local_inventories_id` (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

