DROP TABLE IF EXISTS `product_selections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_selections` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '选品ID',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `product_title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品标题',
  `url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL',
  `asin` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ASIN',
  `image_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片链接',
  `rating` float DEFAULT NULL COMMENT '评分',
  `review_count` int DEFAULT NULL COMMENT '评论数',
  `keywords` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键词',
  `price` decimal(12,2) DEFAULT NULL COMMENT '价格',
  `commission` decimal(12,2) DEFAULT NULL COMMENT '佣金',
  `first_leg_cost` decimal(12,2) DEFAULT NULL COMMENT '头程',
  `last_mile_cost` decimal(12,2) DEFAULT NULL COMMENT '尾程',
  `weight_kg` float DEFAULT NULL COMMENT '重量(kg)',
  `cost_at_15_profit` decimal(12,2) DEFAULT NULL COMMENT '15%毛利时成本',
  `product_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型',
  `monthly_sales` int DEFAULT NULL COMMENT '近一个月销量',
  `traffic_trend` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流量趋势',
  `seasonality` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '季节性判断',
  `infringement_analysis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '侵权分析',
  `traffic_score` float DEFAULT NULL COMMENT '流量评分',
  `sales_score` float DEFAULT NULL COMMENT '销量评分',
  `rating_score` float DEFAULT NULL COMMENT '星级评分',
  `penalty_factor` float DEFAULT NULL COMMENT '惩罚因子',
  `composite_score` float DEFAULT NULL COMMENT '综合评分',
  `ai_raw_response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'AI原始返回',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `infringement_conclusion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '侵权分析结论',
  `traffic_score_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流量评分结果',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `ix_product_selections_asin` (`asin`) USING BTREE,
  KEY `ix_product_selections_tenant_id` (`tenant_id`) USING BTREE,
  KEY `ix_product_selections_id` (`id`) USING BTREE,
  CONSTRAINT `product_selections_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
