INSERT INTO `review_analyses` VALUES (714,1,1186,'deepseek-v4-flash','负面',3,'[\"粉色字母实际颜色比描述照片更柔和，存在色差\"]','[\"颜色偏差\", \"产品描述不准确\"]','[\"改进产品照片颜色准确性，确保与实物一致\", \"在描述中注明颜色可能与实物略有差异\"]','用户反馈粉色字母颜色比照片更柔和（浅），虽无法退货但整体效果可接受，蜜蜂和花朵图案满意。','{\"sentiment\":\"负面\",\"sentiment_score\":3,\"key_points\":[\"粉色字母实际颜色比描述照片更柔和，存在色差\"],\"topics\":[\"颜色偏差\",\"产品描述不准确\"],\"suggestions\":[\"改进产品照片颜色准确性，确保与实物一致\",\"在描述中注明颜色可能与实物略有差异\"],\"summary\":\"用户反馈粉色字母颜色比照片更柔和（浅），虽无法退货但整体效果可接受，蜜蜂和花朵图案满意。\",\"importance_level\":\"high\"}',NULL,'2026-06-04 07:00:04','2026-06-04 07:00:04',NULL);
/*!40000 ALTER TABLE `review_analyses` ENABLE KEYS */;
UNLOCK TABLES;

