INSERT INTO `reviews` VALUES (1186,1,127,409,'B0CYSZ9HZL','Courtney',3,'More pastel than expected','The pink letters are much more pastel than the description photo leads you to believe. I ordered these pretty early and by the time I opened them it was too late to return. Still worked out ok. The bees and flowers are great.','2026-05-05 00:00:00','2026-05-09 17:08:20','云南金顺公司','美国',0,'new','2026-05-09 17:08:21','2026-05-20 18:01:33',NULL,'粉色字母实际上比描述照片中让人以为的要柔和得多。我很早就订购了这些，等打开时已经太晚无法退货了。不过最终效果还是可以的。蜜蜂和花朵图案很棒。','比预期更柔和','high');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

